import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"开发指南","description":"","frontmatter":{},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md","lastUpdated":1765911594000}`),a={name:`development/index.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /development.md for this page in Markdown format</div><h1 id="开发指南" tabindex="-1">开发指南 <a class="header-anchor" href="#开发指南" aria-label="Permalink to “开发指南”">​</a></h1><h2 id="编译文档" tabindex="-1">编译文档 <a class="header-anchor" href="#编译文档" aria-label="Permalink to “编译文档”">​</a></h2><p>Xray 支持各种平台, 您可以在多种平台上自行进行交叉编译。</p><p>请点击<a href="./intro/compile.html">编译文档</a>以查看具体编译相关内容。</p><h2 id="设计思路" tabindex="-1">设计思路 <a class="header-anchor" href="#设计思路" aria-label="Permalink to “设计思路”">​</a></h2><p>Xray 内核提供了一个平台，在其之上可以进二次开发。</p><p>这个章节阐述了 Xray 的设计目标和架构。</p><p>请点击<a href="./intro/design.html">设计思路</a>以了解 Xray 的设计目标和架构。</p><h2 id="开发规范" tabindex="-1">开发规范 <a class="header-anchor" href="#开发规范" aria-label="Permalink to “开发规范”">​</a></h2><p>这个章节阐述了获取代码,进行开发,提交 PR 的流程中需要遵循的准则, 以及相关的编码规范。</p><p>请点击<a href="./intro/guide.html">开发规范</a>查看 Xray 开发中应遵循的准则。</p><h2 id="协议详解" tabindex="-1">协议详解 <a class="header-anchor" href="#协议详解" aria-label="Permalink to “协议详解”">​</a></h2><p>Xray 用到了很多种协议, 您可以通过各种途径获得协议的详细描述。</p><h3 id="vless-协议" tabindex="-1"><a href="./protocols/vless.html">VLESS 协议</a> <a class="header-anchor" href="#vless-协议" aria-label="Permalink to “VLESS 协议”">​</a></h3><p>VLESS 是一个无状态的轻量传输协议，可以作为 Xray 客户端和服务器之间的桥梁。</p><h3 id="vmess-协议" tabindex="-1"><a href="./protocols/vmess.html">VMess 协议</a> <a class="header-anchor" href="#vmess-协议" aria-label="Permalink to “VMess 协议”">​</a></h3><p>VMess 是一个加密传输协议，可以作为 Xray 客户端和服务器之间的桥梁。</p><h3 id="mux-cool-协议" tabindex="-1"><a href="./protocols/muxcool.html">Mux.Cool 协议</a> <a class="header-anchor" href="#mux-cool-协议" aria-label="Permalink to “Mux.Cool 协议”">​</a></h3><p>Mux.Cool 协议是一个多路复用传输协议，用于在一条已建立的数据流中传输多个各自独立的数据流。</p><h3 id="mkcp-协议" tabindex="-1"><a href="./protocols/mkcp.html">mKCP 协议</a> <a class="header-anchor" href="#mkcp-协议" aria-label="Permalink to “mKCP 协议”">​</a></h3><p>mKCP 是流式传输协议，由 <a href="https://github.com/skywind3000/kcp" target="_blank" rel="noreferrer">KCP 协议</a>修改而来，可以按顺序传输任意的数据流。</p>`,22)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};